    mock_job = mock.Mock(
        spec=qai_hub.CompileJob,
        job_id=job_id,
        device=qai_hub.Device("android"),
        model="model.pt",  # string for ease of testing
        target_model=None,
        date=datetime.now(),
        options="--target_runtime tflite",
        verbose=False,
        shapes={"a": (1, 224, 224)},
        calibration_dataset=None,
        project_id="cloned-project",
    )
    # Mock uses name= argument for something else
    mock_job.name = "fancy_pt"

    def mock_get_dataset(dataset_id):
        assert dataset_id == "dabcd1234"
        return mock_dataset

    mock_client = mock.Mock(spec=qai_hub.Client)
    mock_client.submit_compile_job.return_value = None
    mock_client.get_job.return_value = mock_job
    mock_client.get_dataset.side_effect = mock_get_dataset

    with (
        mock.patch("qai_hub.Client", return_value=mock_client),
        mock.patch("os.path.exists", return_value=True),
    ):
        args = get_cli_parser().parse_args(
            ["submit-compile-job"] + input_args,
        )
        run_cli(args)
        wait = expected_results.pop("wait", False)
        mock_client.submit_compile_job.assert_called_once_with(**expected_results)
        if wait:
            mock_job.wait.assert_called()
        else:
            mock_job.wait.assert_not_called()


