    def test_configure_creates_backup_on_overwrite(self, temp_dir, monkeypatch):
        """Test that configure creates a backup when overwriting an existing config."""
        # Arrange
        config_file = temp_dir / "client.ini"

        def mock_get_config_path(profile=None, expanduser=True):
            return str(config_file)

        monkeypatch.setattr("qai_hub._cli.get_config_path", mock_get_config_path)

        args = get_cli_parser().parse_args(
            ["configure", "--api_token", "original_token"]
        )
        run_cli(args)

        # Act
        args = get_cli_parser().parse_args(["configure", "--api_token", "new_token"])
        run_cli(args)

        # Assert
        backup_file = Path(f"{config_file}.bak")
        assert backup_file.exists()

        backup_config = configparser.ConfigParser()
        backup_config.read(backup_file)
        assert backup_config.get("api", "api_token") == "original_token"

        new_config = configparser.ConfigParser()
        new_config.read(config_file)
        assert new_config.get("api", "api_token") == "new_token"
